1	import {
2	  GenMapping,
3	  maybeAddMapping,
4	  setSourceContent,
5	  allMappings,
6	  toEncodedMap,
7	  toDecodedMap,
8	} from "@jridgewell/gen-mapping";
9	
10	import type {
11	  EncodedSourceMap,
12	  DecodedSourceMap,
13	  Mapping,
14	} from "@jridgewell/gen-mapping";
15	
16	import type {
17	  InvalidOriginalMapping,
18	  OriginalMapping,
19	  SourceMapInput,
20	} from "@jridgewell/trace-mapping";
21	import { originalPositionFor, TraceMap } from "@jridgewell/trace-mapping";
22	
23	/**
24	 * Build a sourcemap.
25	 */
26	
27	export default class SourceMap {
28	  private _map: GenMapping;
29	  private _rawMappings: Mapping[] | undefined;
30	  private _sourceFileName: string | undefined;
31	
32	  // Any real line is > 0, so init to 0 is fine.
33	  private _lastGenLine = 0;
34	  private _lastSourceLine = 0;
35	
36	  // Source columns can be 0, but we only check in unison with sourceLine, which
37	  // inits to an impossible value. So init to 0 is fine.
38	  private _lastSourceColumn = 0;
39	
40	  public _inputMap: TraceMap | null = null;
41	
42	  constructor(
43	    opts: {
44	      sourceFileName?: string;
45	      sourceRoot?: string;
46	      inputSourceMap?: SourceMapInput;
47	    },
48	    code: string | Record<string, string> | null | undefined,
49	  ) {
50	    const map = (this._map = new GenMapping({ sourceRoot: opts.sourceRoot }));
51	    this._sourceFileName = opts.sourceFileName?.replace(/\\/g, "/");
52	    this._rawMappings = undefined;
53	
54	    if (opts.inputSourceMap) {
55	      this._inputMap = new TraceMap(opts.inputSourceMap);
56	      const resolvedSources = this._inputMap.resolvedSources;
57	      if (resolvedSources.length) {
58	        for (let i = 0; i < resolvedSources.length; i++) {
59	          setSourceContent(
60	            map,
61	            resolvedSources[i],
62	            // @ts-expect-error FIXME: this._inputMap.sourcesContent?.[i] may be undefined, which is not acceptable by setSourceContent
63	            this._inputMap.sourcesContent?.[i],
64	          );
65	        }
66	      }
67	    }
68	
69	    if (typeof code === "string" && !opts.inputSourceMap) {
70	      setSourceContent(map, this._sourceFileName!, code);
71	    } else if (typeof code === "object") {
72	      for (const sourceFileName of Object.keys(code!)) {
73	        setSourceContent(
74	          map,
75	          sourceFileName.replace(/\\/g, "/"),
76	          code![sourceFileName],
77	        );
78	      }
79	    }
80	  }
81	
82	  /**
83	   * Get the sourcemap.
84	   */
85	  get(): EncodedSourceMap {
86	    return toEncodedMap(this._map);
87	  }
88	
89	  getDecoded(): DecodedSourceMap {
90	    return toDecodedMap(this._map);
91	  }
92	
93	  getRawMappings(): Mapping[] {
94	    return (this._rawMappings ||= allMappings(this._map));
95	  }
96	
97	  /**
98	   * Mark the current generated position with a source position. May also be passed null line/column
99	   * values to insert a mapping to nothing.
100	   */
101	
102	  mark(
103	    generated: { line: number; column: number },
104	    line?: number,
105	    column?: number,
106	    identifierName?: string | null,
107	    identifierNamePos?: { line: number; column: number },
108	    filename?: string | null,
109	  ) {
110	    this._rawMappings = undefined;
111	
112	    let originalMapping: OriginalMapping | InvalidOriginalMapping | undefined;
113	
114	    if (line != null) {
115	      if (this._inputMap) {
116	        // This is the lookup for this mark
117	        originalMapping = originalPositionFor(this._inputMap, {
118	          line,
119	          column: column!,
120	        });
121	
122	        // If the we found a name, nothing else needs to be done
123	        // Maybe we're marking a `(` and the input map already had a name attached there,
124	        // or we're marking a `(` and the sourcemap spanned a `foo(`,
125	        // or we're marking an identifier, etc.
126	        if (!originalMapping.name && identifierNamePos) {
127	          // We're trying to mark a `(` (as that's the only thing that provides
128	          // an identifierNamePos currently), and we the AST had an identifier attached.
129	          // Lookup it's original name.
130	          const originalIdentifierMapping = originalPositionFor(
131	            this._inputMap,
132	            identifierNamePos,
133	          );
134	          if (originalIdentifierMapping.name) {
135	            identifierName = originalIdentifierMapping.name;
136	          }
137	        }
138	      } else {
139	        originalMapping = {
140	          name: null,
141	          source: filename?.replace(/\\/g, "/") || this._sourceFileName!,
142	          line: line,
143	          column: column!,
144	        };
145	      }
146	    }
147	
148	    // @ts-expect-error FIXME: original cannot be InvalidOriginalMapping
149	    maybeAddMapping(this._map, {
150	      name: identifierName,
151	      generated,
152	      source: originalMapping?.source,
153	      original: originalMapping,
154	    });
155	  }
156	}
